def search_all(q):
    page_index=0; page_limit=20; out=[]
    while True:
        resp=apis.simple_note.search_notes(access_token=st, query=q, page_index=page_index, page_limit=page_limit)
        if not resp: break
        out.extend(resp)
        page_index+=1
    return out

